type EnvRecord = Record<string, string | undefined>

function readEnv(): EnvRecord {
  return import.meta.env as EnvRecord
}

export function getDataMode(): string {
  return readEnv().VITE_DATA_MODE ?? 'demo'
}

export function isDemoDataMode(): boolean {
  return getDataMode() === 'demo'
}

/** test 构建开启：注入完整防汛演示数据并跳过真实登录/接口 */
export function isFloodMockEnabled(): boolean {
  const env = readEnv()
  const flag = env.VITE_FLOOD_MOCK
  if (flag === 'true' || flag === '1') return true
  if (flag === 'false' || flag === '0') return false
  return isDemoDataMode()
}

export const DEMO_AUTH_TOKEN = 'flood-mock-token-v1'

import type { FloodRecord, InspectionType } from '../stores/flood'
import { initialValues, ticketPlaces, ticketTitles } from '../types/inspection'

export const FLOOD_DEMO_SEED_VERSION = 2

const DEMO_PHOTO = '/static/assets/e3436.png'
const photo = (n = 1) => Array.from({ length: n }, (_, i) => ({ url: DEMO_PHOTO, status: 'done' as const, name: `现场${i + 1}.png` }))

function isoHoursAgo(hours: number) {
  return new Date(Date.now() - hours * 3600_000).toISOString()
}

function preValues(index: number) {
  const base = initialValues('pre') as Record<string, unknown>
  base.date = '2026-10-28'
  base.people = 2 + (index % 4)
  base.hazards = index % 3
  base.resolved = index % 2
  base.drains = index % 2 ? '是' : '否'
  base.rooms = '是'
  base.pipes = index % 3 ? '是' : '否'
  base.vehicles = index % 5
  return base
}

function midValues(index: number) {
  const base = initialValues('mid') as Record<string, unknown>
  const notes = base.notes as Record<string, string>
  if (index === 0) {
    base.road = '轻度积水'
    base.garage = '无倒灌'
    base.pump = '正常'
    notes.road = '南门辅路少量积水，已放置警示牌'
    base.photos = photo(2)
  } else if (index === 1) {
    base.road = '中度积水'
    base.garage = '局部倒灌'
    base.tree = '有倾倒/偏斜'
    notes.garage = 'B1 东侧排水沟淤堵，已联系疏通'
    base.photos = photo(3)
  } else {
    base.road = '严重积水'
    base.elevator = '异常'
    base.power = '有隐患'
    notes.elevator = '低区电梯机房门口渗水，已断电防护'
    base.photos = photo(1)
  }
  return base
}

function postValues(index: number) {
  const base = initialValues('post') as Record<string, unknown>
  const notes = base.notes as Record<string, string>
  if (index === 0) {
    base.roadSubsidence = '无'
    base.drainBlock = '无'
    notes.road = '汛后道路巡查正常'
  } else if (index === 1) {
    base.roadSeepage = '有'
    base.manhole = '有'
    notes.drain = '2 处雨水井需清掏，已列入整改'
    base.photos = photo(2)
  } else {
    base.garageBackflow = '有'
    base.ledgerPlan = '无'
    notes.underground = '车库出入口曾倒灌，沙袋已回收清点'
    base.photos = photo(1)
  }
  return base
}

function inspectionRecord(kind: InspectionType, index: number, hoursAgo: number, values: Record<string, unknown>, complexName?: string): FloodRecord {
  const place = complexName ?? ticketPlaces[kind]
  const no = kind === 'pre' ? `FX-2026-PRE-${String(index + 1).padStart(3, '0')}` : kind === 'mid' ? `FX-2026-MID-${String(index + 1).padStart(3, '0')}` : `FX-2026-POST-${String(index + 1).padStart(3, '0')}`
  return {
    id: no,
    inspectionNo: no,
    kind,
    status: 'submitted',
    createdAt: isoHoursAgo(hoursAgo),
    checkDate: String(values.date ?? isoHoursAgo(hoursAgo).slice(0, 10)),
    complexId: `cx-${kind}-${index}`,
    complexName: place,
    subject: `${place} · ${ticketTitles[kind]}`,
    values: JSON.parse(JSON.stringify(values)),
  }
}

function rescueRecord(index: number, level: '一般' | '紧急' | '特级', hoursAgo: number): FloodRecord {
  const danger = index === 0 ? '地下车库入口积水，需要排水' : '配电间周边积水，担心漏电'
  const support = index === 0 ? '申请抽水泵及沙袋' : '需要电工现场排查并加装挡水板'
  const no = `QY-2026-${String(index + 1).padStart(3, '0')}`
  const values = {
    contact: index === 0 ? '演示联系人' : '李敏',
    phone: index === 0 ? '13812345678' : '13900001111',
    level,
    danger,
    support,
    photos: photo(2),
    complexId: `cx-rescue-${index}`,
    complexName: index === 0 ? '永林新村' : '苏锦二村',
  }
  return {
    id: no,
    inspectionNo: no,
    kind: 'rescue',
    status: 'submitted',
    createdAt: isoHoursAgo(hoursAgo),
    complexId: String(values.complexId),
    complexName: String(values.complexName),
    values: JSON.parse(JSON.stringify(values)),
    rescue: {
      contactName: String(values.contact),
      contactPhone: String(values.phone),
      urgentLevel: level === '一般' ? '1' : level === '紧急' ? '2' : '3',
      dangerDesc: danger,
      supportDesc: support,
    },
  }
}

/** 覆盖历史列表、筛选、分页、详情各分区展示所需的本地演示数据集 */
export function buildFloodDemoSeed(): { seedVersion: number; drafts: FloodRecord['values']; records: FloodRecord[] } {
  const records: FloodRecord[] = []
  for (let i = 0; i < 11; i++) {
    records.push(inspectionRecord('pre', i, 2 + i, preValues(i)))
  }
  for (let i = 0; i < 3; i++) {
    records.push(inspectionRecord('mid', i, 20 + i, midValues(i)))
  }
  for (let i = 0; i < 3; i++) {
    records.push(inspectionRecord('post', i, 40 + i, postValues(i)))
  }
  records.push(rescueRecord(0, '紧急', 6))
  records.push(rescueRecord(1, '特级', 8))

  const drafts = {
    pre: { values: { ...preValues(0), people: 1, date: '2026-10-29' }, savedAt: isoHoursAgo(1) },
